import{_ as t,o as a,c as o,a6 as n}from"./chunks/framework.CKIbuWFA.js";const p=JSON.parse('{"title":"Sign in to your Cloud account","description":"","frontmatter":{"title":"Sign in to your Cloud account","docId":"user.cloud.account","translationKey":"user.cloud.account","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"02b7718e7fc7b2a53b68ee1c6e19e622608a6fdfc7eac553879c474ca69ea74b","translationRevision":"02b7718e7fc7b2a53b68ee1c6e19e622608a6fdfc7eac553879c474ca69ea74b","order":10},"headers":[],"relativePath":"en/user/cloud/account.md","filePath":"en/user/cloud/account.md","lastUpdated":1794611623000}'),r={name:"en/user/cloud/account.md"};function i(s,e,c,l,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="sign-in-to-your-cloud-account" tabindex="-1">Sign in to your Cloud account <a class="header-anchor" href="#sign-in-to-your-cloud-account" aria-label="Permalink to &quot;Sign in to your Cloud account {#sign-in-to-your-cloud-account}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Connect the desktop app to its configured Cloud service for account-based catalog and collaboration operations. You need network access, a system browser and a working operating system credential store. Local editing remains useful without Cloud; a Cloud session does not authenticate your TikTok LIVE connection.</p><h2 id="sign-in-and-verify-identity" tabindex="-1">Sign in and verify identity <a class="header-anchor" href="#sign-in-and-verify-identity" aria-label="Permalink to &quot;Sign in and verify identity {#sign-in-and-verify-identity}&quot;">​</a></h2><ol><li>Open <strong>Settings → Account</strong>. Read the current state before starting another login.</li><li>Select <strong>Sign in</strong>. The desktop starts a local callback receiver and opens the configured login page in the system browser.</li><li>Complete the service&#39;s login flow and return to TikTools. If the browser did not open, use the login URL shown by the app for this attempt. Treat that URL as private and do not post it publicly.</li><li>Wait for the account state to become signed in. Confirm the displayed name or email before opening a private catalog or team.</li><li>Open the Account diagnostics disclosure if the status reports an error. Use <strong>Cancel</strong> to abandon an unfinished attempt rather than leaving several attempts active.</li><li>When finished on a shared computer, select <strong>Sign out</strong> and verify the account state changed.</li></ol><p>The native host handles the session token. It stores credentials through the operating system credential store and keeps only nonsecret status in the frontend. There is no plaintext-file fallback when secure storage is unavailable. A copied data folder is not a portable signed-in session.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Native sign-in, restore and sign-out are available in hosts built with Cloud authentication. A configured account can be restored on restart and revalidated with the service. An unconfigured or unsupported host cannot be fixed by entering a different TikTok cookie.</p><p>Service login availability and real provider/platform acceptance depend on the deployed service and your machine. Local validation does not prove every production sign-in route works.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>For a cancelled or expired attempt, start a fresh login after closing the old one. For network or service errors, preserve the diagnostic code and retry after recovery. For a credential-store error, restore the operating system&#39;s secure-storage availability; do not paste a bearer token into settings or a support message. See <a href="./changes.html">Changes</a> for explicit synchronization and <a href="./collaboration.html">collaboration</a> for separate access grants.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Sign-out deletes local credentials and clears the local account context before attempting server revocation on a best-effort basis. A signed-out UI confirms local removal, not successful remote token revocation during network failure. Use service-side session administration if your service provides it. Export relevant Diagnostics before signing out or changing a known account; that UI history is cleared. TikTok cookies and remote-host sessions are separate identities.</p>',13)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
